package com.bank.compliance;

import java.util.logging.Logger;

public class PatternMatcher {

    private static final Logger log = Logger.getLogger(PatternMatcher.class.getName());

    public int longestCommonSubsequence(String a, String b) {
        int m = a.length(), n = b.length();
        int[][] dp = new int[m + 1][n + 1];            // zero border included
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (a.charAt(i - 1) == b.charAt(j - 1)) {
                    dp[i][j] = dp[i - 1][j - 1] + 1;    // match ⇒ diagonal + 1
                } else {
                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]); // drop one side
                }
            }
        }
        int result = dp[m][n];
        log.info(() -> "LCS(" + a + "," + b + ") = " + result);
        return result;
    }
}
