package com.bank.compliance;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class LcsDemo {

    private static final Logger log = Logger.getLogger(LcsDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Compliance Pattern Matcher (LCS)");
        PatternMatcher matcher = new PatternMatcher();
        log.info("abcde vs ace → " + matcher.longestCommonSubsequence("abcde", "ace")); // 3
        log.info("abc vs def → " + matcher.longestCommonSubsequence("abc", "def"));     // 0
    }
}
